def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)

    main = max(components, key=len)
    main_set = set(main)
    r0 = min(r for r, c in main)
    r1 = max(r for r, c in main)
    c0 = min(c for r, c in main)
    c1 = max(c for r, c in main)
    patch = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    H, W = len(patch), len(patch[0])

    external = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in main_set:
                external.setdefault(grid[r][c], []).append((r, c))

    labels = [color for color, pts in external.items() if len(pts) == 1]
    anchors = {}
    for color in labels:
        found = [(r, c) for r in range(H) for c in range(W)
                 if patch[r][c] == color]
        if len(found) == 1:
            anchors[color] = found[0]

    def roles(points):
        rows = [p[0] for p in points.values()]
        cols = [p[1] for p in points.values()]
        return {color: (0 if p[0] == min(rows) else 1,
                        0 if p[1] == min(cols) else 1)
                for color, p in points.items()}

    target_roles = roles({
        color: (pts[0][0], pts[0][1])
        for color, pts in external.items()
        if color in anchors and len(pts) == 1
    })

    transforms = [
        (H, W, lambda r, c: (r, c)),
        (W, H, lambda r, c: (c, H - 1 - r)),
        (H, W, lambda r, c: (H - 1 - r, W - 1 - c)),
        (W, H, lambda r, c: (W - 1 - c, r)),
        (H, W, lambda r, c: (r, W - 1 - c)),
        (H, W, lambda r, c: (H - 1 - r, c)),
        (W, H, lambda r, c: (c, r)),
        (W, H, lambda r, c: (W - 1 - c, H - 1 - r)),
    ]

    chosen = transforms[-1]
    best = -1
    for oh, ow, mapper in transforms:
        mapped = {color: mapper(*pos) for color, pos in anchors.items()}
        if not mapped:
            continue
        mapped_roles = roles(mapped)
        score = sum(mapped_roles.get(color) == role
                    for color, role in target_roles.items())
        if score > best:
            best = score
            chosen = (oh, ow, mapper)

    oh, ow, mapper = chosen
    out = [[1] * ow for _ in range(oh)]
    for r in range(H):
        for c in range(W):
            nr, nc = mapper(r, c)
            out[nr][nc] = patch[r][c]
    return out
